import java.util.*;

public class Main {
    int[] runningSum(int[] nums) {
        int n = nums.length;
        int[] result = new int[n];
        for (int i = 0; i < n; i++) {
            int total = 0;
            for (int j = 0; j <= i; j++) {                              // resums from the very start every single time
                total += nums[j];
            }
            result[i] = total;
        }
        return result;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        System.out.println(Arrays.toString(solution.runningSum(new int[]{1, 2, 3, 4})));
    }
}

