def running_sum(nums):
    result = list(nums)                                         # start as a copy, then accumulate in place
    for i in range(1, len(result)):
        result[i] += result[i - 1]                                   # reuse the immediately preceding running total
    return result


if __name__ == "__main__":
    print(running_sum([1, 2, 3, 4]))

